/* 冥冥星球 · Stripe 訂閱後端
 * 同時做兩件事：
 *   1) 託管網站（直接讀 /workspace/mx 靜態檔，開 http://localhost:8788 即用）
 *   2) 提供訂閱 API：建立 Checkout、接收 webhook、查詢訂閱狀態
 *
 * 設定（環境變數或下方 CONFIG 直接填）：
 *   STRIPE_SECRET_KEY               Stripe 金鑰（sk_live_... / sk_test_...）
 *   STRIPE_MONTHLY_PRICE_ID_TWD     月訂閱 Price ID（台幣 NT$95/月）
 *   STRIPE_MONTHLY_PRICE_ID_HKD     月訂閱 Price ID（港幣 HK$24/月）
 *   STRIPE_WEBHOOK_SECRET           webhook 簽章密鑰（stripe listen 會給）
 *   PORT（預設 8788）
 *
 * 正式上線：把本檔部署到你的主機（HTTPS），並把前端 STRIPE_API 指向該網址。
 */
const fs = require('fs');
const path = require('path');
const http = require('http');
const stripe = require('stripe');

const CONFIG = {
  port: process.env.PORT || 8788,
  stripeKey: process.env.STRIPE_SECRET_KEY || '',
  webhookSecret: process.env.STRIPE_WEBHOOK_SECRET || '',
  /* 只保留月訂閱（雙幣別） */
  prices: {
    TWD: { monthly: process.env.STRIPE_MONTHLY_PRICE_ID_TWD || '' },
    HKD: { monthly: process.env.STRIPE_MONTHLY_PRICE_ID_HKD || '' },
  },
  trialDays: Number(process.env.STRIPE_TRIAL_DAYS || 30),   // 首月免費試用
  appUrl: (()=>{ const u = process.env.APP_URL || process.env.RENDER_EXTERNAL_URL || 'http://localhost:8788/'; return u.endsWith('/') ? u : u+'/'; })(),
  subsFile: process.env.SUBS_FILE || path.join(__dirname, 'subs.json'),
  staticDir: path.join(__dirname, 'mx'),
};
const client = CONFIG.stripeKey ? stripe(CONFIG.stripeKey) : null;
if (!client) console.log('⚠️  尚未設定 STRIPE_SECRET_KEY，/create-checkout 會回報未配置（可先跑起來看靜態站）');

/* ---------- 小工具 ---------- */
function send(res, code, body){ res.writeHead(code, {'Content-Type':'application/json; charset=utf-8'}); res.end(typeof body==='string'? body : JSON.stringify(body)); }
function readJson(req){ return new Promise((ok,err)=>{ let d=''; req.on('data',c=>d+=c); req.on('end',()=>{ try{ ok(d?JSON.parse(d):{}); }catch(e){ err(e); } }); }); }
function readRaw(req){ return new Promise((ok,err)=>{ let d=''; req.on('data',c=>d+=c); req.on('end',()=>ok(d)); }); }
function loadSubs(){ try{ return JSON.parse(fs.readFileSync(CONFIG.subsFile,'utf8')); }catch(e){ return {}; } }
function saveSubs(o){ fs.writeFileSync(CONFIG.subsFile, JSON.stringify(o,null,2)); }

/* ---------- API ---------- */
async function createCheckout(req,res){
  if(!client) return send(res,500,{error:'Stripe 未配置：請設定 STRIPE_SECRET_KEY'});
  const {user,currency} = await readJson(req);
  const cur = String(currency||'TWD').toUpperCase()==='HKD' ? 'HKD' : 'TWD';
  const priceId = (CONFIG.prices[cur]||{}).monthly;
  if(!priceId) return send(res,400,{error:'缺少 '+cur+' 的 Price ID（請設定 STRIPE_MONTHLY_PRICE_ID_'+cur+'）'});
  try{
    const subData = { trial_period_days:CONFIG.trialDays, metadata:{user:user||'anon', plan:'monthly', currency:cur} };
    const session = await client.checkout.sessions.create({
      mode:'subscription',
      client_reference_id: user || 'anon',
      line_items:[{price:priceId, quantity:1}],
      subscription_data: subData,
      allow_promotion_codes:true,
      success_url: CONFIG.appUrl + '?checkout=success&user=' + encodeURIComponent(user||'anon') + '&plan=monthly',
      cancel_url: CONFIG.appUrl,
    });
    send(res,200,{url:session.url});
  }catch(e){ send(res,500,{error:e.message}); }
}

async function handleWebhook(req,res){
  if(!client) return send(res,500,'Stripe 未配置');
  const sig = req.headers['stripe-signature'];
  let event;
  try{ event = client.webhooks.constructEvent(await readRaw(req), sig, CONFIG.webhookSecret); }
  catch(e){ return send(res,400,'webhook 簽章錯誤: '+e.message); }
  const subs = loadSubs();
  const obj = event.data.object;
  if(event.type==='checkout.session.completed'){
    const u = obj.client_reference_id;
    if(u) subs[u] = Object.assign(subs[u]||{}, {stripeCustomer:obj.customer, status:'pending', updated:Date.now()});
  }
  if(event.type==='customer.subscription.created' || event.type==='customer.subscription.updated' || event.type==='customer.subscription.deleted'){
    const u = obj.metadata && obj.metadata.user;
    if(u){
      const active = (obj.status==='active'||obj.status==='trialing');
      const meta = obj.metadata||{};
      const price = obj.items && obj.items.data && obj.items.data[0] && obj.items.data[0].price;
      const plan = meta.plan || 'monthly';
      subs[u] = Object.assign(subs[u]||{}, {
        status: obj.status==='canceled' ? 'canceled' : (active?'active':'inactive'),
        plan,
        currency: meta.currency || (price && price.currency) || null,
        stripeCustomer: obj.customer,
        until: obj.current_period_end ? obj.current_period_end*1000 : null,
        updated: Date.now(),
      });
    }
  }
  saveSubs(subs);
  send(res,200,{received:true});
}

function status(req,res,url){
  const u = new URL(url,'http://x').searchParams.get('user');
  const s = (u && loadSubs()[u]) || {};
  send(res,200,{ subscribed: s.status==='active', status:s.status||'none', plan:s.plan||null, currency:s.currency||null, until:s.until||null, stripeCustomer: s.stripeCustomer||null });
}

/* ---------- 取消 / 管理訂閱：Stripe Customer Portal ----------
 * 用戶從前端點「取消訂閱」→ 跳到 Stripe 託管的客戶門戶 → 自己取消、改卡、下載收據
 * 安全：需要知道 stripeCustomer id（從 subs.json 取）；若無則報錯提示先付款
 */
async function createPortal(req,res){
  if(!client) return send(res,500,{error:'Stripe 未配置'});
  const {user} = await readJson(req);
  const sub = (user && loadSubs()[user]) || {};
  if(!sub.stripeCustomer) return send(res,400,{error:'找不到客戶記錄，請確認你已付款'});
  try{
    const session = await client.billingPortal.sessions.create({
      customer: sub.stripeCustomer,
      return_url: CONFIG.appUrl,
    });
    send(res,200,{url:session.url});
  }catch(e){ send(res,500,{error:e.message}); }
}

/* ---------- 開發用：模擬 webhook（?dev=fakehook）----------
 * 讓你在不接真 Stripe 的情況下，模擬「付款成功 → 訂閱狀態寫入」的全鏈路。
 * 用法（沙箱或正式站都可以）：
 *   POST /webhook?dev=1&user=USER_ID&plan=monthly&currency=TWD
 *   -> 直接寫 subs.json[USER_ID]=active，相當於 webhook 寫入
 * 僅當 STRIPE_DEV_MODE=1 環境變數為開啟時生效（默認關閉，保護正式環境）
 */
async function devFakeHook(req,res,url){
  if(process.env.STRIPE_DEV_MODE!=='1') return send(res,403,{error:'STRIPE_DEV_MODE 為關閉，正式環境不開放'});
  const p = new URL(url,'http://x').searchParams;
  const u = p.get('user')||'dev_user';
  const plan = p.get('plan')||'monthly';
  const currency = (p.get('currency')||'TWD').toUpperCase();
  const subs = loadSubs();
  subs[u] = Object.assign(subs[u]||{}, {
    status:'active', plan, currency,
    until: Date.now()+30*864e5, updated: Date.now(),
    note:'dev fake hook',
  });
  saveSubs(subs);
  send(res,200,{ok:true, subs:subs[u], tip:'前端 syncStripe() 會讀到 active'});
}

/* ---------- 靜態檔託管（優先內嵌檔案，找不到再讀磁碟 mx/）---------- */
const EMBED={
  '/index.html':{t:'text/html; charset=utf-8',b64:''},
  '/sw-med.js':{t:'text/javascript',b64:''},
  '/manifest-med.webmanifest':{t:'application/manifest+json',b64:''},
  '/mx-icon-192.png':{t:'image/png',b64:''},
  '/mx-icon-512.png':{t:'image/png',b64:''}
};   // 打包部署版時注入 base64；本地為空 → 讀磁碟
const MIME={'.html':'text/html','.js':'text/javascript','.css':'text/css','.json':'application/json','.png':'image/png','.svg':'image/svg+xml','.webmanifest':'application/manifest+json','.ico':'image/x-icon'};
function serveStatic(req,res){
  let p = decodeURIComponent(req.url.split('?')[0]);
  if(p==='/'||p==='') p='/index.html';
  const f = EMBED[p];
  if(f){ res.writeHead(200,{'Content-Type':f.t}); res.end(Buffer.from(f.b64,'base64')); return; }
  const fp = path.join(CONFIG.staticDir, path.normalize(p).replace(/^(\.\.[/\\])+/,''));
  fs.readFile(fp,(e,buf)=>{
    if(e){ res.writeHead(404,{'Content-Type':'text/plain; charset=utf-8'}); res.end('404'); return; }
    res.writeHead(200,{'Content-Type':MIME[path.extname(fp)]||'application/octet-stream'});
    res.end(buf);
  });
}

/* ---------- 路由 ---------- */
const server = http.createServer(async (req,res)=>{
  try{
if(req.method==='POST' && req.url==='/create-checkout') return createCheckout(req,res);
  if(req.method==='POST' && req.url==='/create-portal') return createPortal(req,res);
  if(req.method==='POST' && req.url.startsWith('/webhook')){
    if(req.url.includes('dev=1')) return devFakeHook(req,res,req.url);
    return handleWebhook(req,res);
  }
    if(req.method==='GET' && req.url.startsWith('/status')) return status(req,res,req.url);
    if(req.method==='GET') return serveStatic(req,res);
    res.writeHead(405); res.end('Method Not Allowed');
  }catch(e){ send(res,500,{error:e.message}); }
});
server.listen(CONFIG.port,()=>console.log(`✅ 冥冥星球伺服器已啟動：http://localhost:${CONFIG.port}  (Stripe ${client?'已連線':'未配置'})`));
